mapper.select:
SELECT  FROM crm_notification_delivery
WHERE tenant_id=#{tenantId} AND recipient_user_id=#{recipientUserId}
  AND notification_id IN #{id}
ORDER BY notification_id,id

mapper.update:
UPDATE crm_notification SET read_at=#{readAt},updated_at=#{readAt},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND recipient_user_id=#{recipientUserId}
  AND version=#{expectedVersion} AND read_at IS NULL

UPDATE crm_notification_delivery SET status='UNKNOWN',provider=NULL,provider_message_id=NULL,
  last_error_masked=#{errorMasked},next_attempt_at=NULL,claim_owner=NULL,claim_expires_at=NULL,
  updated_at=#{finishedAt},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}
  AND status='SENDING' AND claim_owner=#{owner} AND claim_expires_at<#{finishedAt}

mapper.select:
SELECT id,tenant_id AS tenantId,corp_id AS corpId,wecom_userid AS wecomUserid,
  staff_user_id AS staffUserId,enabled AS archiveEnabled,message_enabled AS messageEnabled,version
FROM crm_wecom_staff_account WHERE tenant_id=#{tenantId} AND id=#{id}
